扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: import { Effect } from "effect";
L2: import { brotliDecompress, gunzip, inflate, zstdDecompress } from "node:zlib";
L3: // Far above any real response; OpenRouter's model list is about 0.9 MB.
L4: const maxBody = 4 * 1024 * 1024;
L5: // Asks for an uncompressed body and takes any body as sent: Bun inflates a
L6: // compressed one in full even after the reader stops, so a few KB of brotli
L7: // could take gigabytes. `decompress` is Bun's own option.
L8: function request(url, init) {
L9:     const headers = new Headers(init.headers);
L10:     headers.set("Accept-Encoding", "identity");
L11:     return fetch(url, { ...init, headers, decompress: false });
L12: }
L13: // Asynchronous, so a body crafted to decode slowly doesn't stall OpenCode.
L14: const decoding = (decoder) => (body) => new Promise((resolve, reject) => decoder(body, { maxOutputLength: maxBody }, (error, result) => (error ? reject(error) : resolve(result))));
L15: const decoders = new Map([
L16:     ["gzip", decoding(gunzip)],
L17:     ["x-gzip", decoding(gunzip)],
L18:     ["deflate", decoding(inflate)],
L19:     ["br", decoding(brotliDecompress)],
L20:     ["zstd", decoding(zstdDecompress)],
L21: ]);
L22: // Counts the body as it arrives, so a huge or endless one is cut off rather than
L23: // held whole (leaving the loop cancels the rest), and decodes it with the same
L24: // limit on what it decodes to. Servers code a body once at most, so one coded
L25: // more than once is refused rather than decoded layer by layer.
L26: async function readBody(response) {
L27:     const codings = (response.headers.get("content-encoding") ?? "")
L28:         .split(",")
L29:         .map((coding) => coding.trim().toLowerCase())
L30:         .filter((coding) => coding !== "" && coding !== "identity");
L31:     const decode = codings.length === 1 ? decoders.get(codings[0]) : undefined;
L32:     if (codings.length > 0 && decode === undefined) {
L33:         await response.body?.cancel();
L34:         return { refused: "undecodable" };
L35:     }
L36:     const chunks = [];

{
  "name": "opencode-oauth",
  "version": "0.6.0",
  "description": "OpenCode plugin: sign in to an OpenAI-compatible provider with OAuth 2.0 and PKCE, add its models, and search the web through SearXNG behind the same sign-in",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oauth",
    "oauth2",
    "pkce",
    "oidc",
    "searxng"
  ],
  "license": "MIT",
  "author": "Kevin Park",
  "homepage": "https://github.com/kevinpark1217/opencode-oauth#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kevinpark1217/opencode-oauth.git"
  },
  "bugs": {
    "url": "https://github.com/kevinpark1217/opencode-oauth/issues"
  },
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "packageManager": "bun@1.4.5",
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json",
    "prepack": "bun run build"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.1",
    "effect": "^4.0.1"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "effect": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.4.1",
    "@types/bun": "1.4.5",
    "effect": "4.1.0",
    "typescript": "7.0.2"
  }
}

import { Plugin } from "@opencode/plugin/effect";
import { Effect } from "effect";
import { checkHost } from "./host.js";
import { discoverModels } from "./models.js";
import { parseOptions, registration } from "./oauth.js";
import { search } from "./search.js";
export default Plugin.define({
    id: "opencode-oauth",
    effect: (ctx) => Effect.gen(function* () {
        const options = yield* Effect.sync(() => {
            checkHost(ctx.app.version);
            return parseOptions(ctx.options);
        });
        // OpenCode reruns transforms whenever its registry is rebuilt; one
        // registration keeps the discovered metadata across those reruns.
        const method = registration(options);
        yield* ctx.integration.transform((editor) => {
            editor.method.update(method);
            editor.method.remove(options.provider, { type: "key" });
        });
        if (options.discoverModels !== false)
            yield* discoverModels(ctx, options.provider);
        const searchURL = options.searchURL;
        if (searchURL === undefined)
            return;
        // Not made the default: a plugin's choice would hide the one the user makes
        // in OpenCode, so the config's `websearch` selects it.
        yield* ctx.websearch.transform((editor) => {
            editor.add({
                id: options.provider,
                name: "SearXNG",
                execute: ({ query }) => Effect.gen(function* () {
                    // resolve() renews a token that is about to expire.
                    const connection = yield* ctx.integration.connection.active(options.provider);
                    const credential = connection && (yield* ctx.integration.connection.resolve(connection));
                    if (credential?.type !== "oauth") {
                        return yield* Effect.fail(new Error(`not signed in: run opencode auth login ${options.provider}`));
                    }
                    return yield* search(searchURL, query, credential.access);
                }),
            });
        });
    }),
});
